function onTheory(root){
  const h=root.querySelector('#w-hop');
  if(h){h.innerHTML=`<label>Старт a = <output id="whA">−3</output><input type="range" id="whSa" min="-10" max="10" step="1" value="-3"></label><label>Прибавляем b = <output id="whB">5</output><input type="range" id="whSb" min="-10" max="10" step="1" value="5"></label><div id="whO"></div>`;
    const A=h.querySelector('#whSa'),B=h.querySelector('#whSb');const draw=()=>{const a=+A.value,b=+B.value,c=a+b;h.querySelector('#whA').textContent=N(a);h.querySelector('#whB').textContent=N(b);
      const pic=b===0?nl({min:-20,max:20,pts:[{x:a,t:'старт и финиш'}]}):nl({min:-20,max:20,pts:[{x:a,col:'var(--card)'},{x:c,col:'var(--hl)'}],hops:[{a,b:c,t:SG(b)}]});
      h.querySelector('#whO').innerHTML=`<div style="display:flex;justify-content:center">${pic}</div><div class="small" style="text-align:center">${b===0?'Прибавили 0 — стоим на месте.':`${b>0?'b положительное → шагаем вправо':'b отрицательное → шагаем влево'} на ${Math.abs(b)} ${plural(Math.abs(b),'шаг','шага','шагов')}.`} ${N(a)} + ${S(b)} = <span class="out">${N(c)}</span></div>`;};
    A.oninput=draw;B.oninput=draw;draw();}
  const t=root.querySelector('#w-thermo');
  if(t){t.innerHTML=`<label>Температура: <output id="wtT">−8</output>°<input type="range" id="wtS" min="-30" max="30" step="1" value="-8"></label><div id="wtO" style="display:flex;gap:12px;align-items:center;justify-content:center;flex-wrap:wrap"></div>`;
    const Sl=t.querySelector('#wtS');const draw=()=>{const v=+Sl.value;t.querySelector('#wtT').textContent=v>0?'+'+v:N(v);
      t.querySelector('#wtO').innerHTML=thermo(v,{})+`<div class="small" style="max-width:260px">${v===0?'Ровно ноль — ни мороз, ни тепло.':v<0?`${-v} ${plural(-v,'градус','градуса','градусов')} мороза. До нуля |${N(v)}| = <span class="out">${-v}</span>.`:`${v} ${plural(v,'градус','градуса','градусов')} тепла. |${v}| = <span class="out">${v}</span>.`}<br>${v<-3?`Это холоднее, чем −3°: ${N(v)} < −3.`:v>-3?`Это теплее, чем −3°: ${v>0?'+'+v:N(v)} > −3.`:'Это как раз −3°.'}</div>`;};
    Sl.oninput=draw;draw();}
}

