G(6,()=>{const q=nz(-12,12),b=nz(-9,9);if(q>0&&b>0)return null;const a=q*b;return {type:'num',q:`Вычисли: <span class="m">${N(a)} : ${S(b)}</span>`,ans:q,
short:`${Math.abs(a)} : ${Math.abs(b)} = ${Math.abs(q)}, ${Math.sign(a)===Math.sign(b)?'знаки одинаковые → +':'знаки разные → −'}: ${N(q)}.`,
explain:`Деление — то же правило знаков, что и умножение.<br>1) Модули: ${Math.abs(a)} : ${Math.abs(b)} = ${Math.abs(q)}.<br>2) Знак: ${Math.sign(a)===Math.sign(b)?'одинаковые → «+»':'разные → «−»'}.<br>Ответ: <b>${N(q)}</b>.`,
explain2:`Проверка умножением: ${S(q)} · ${S(b)} = ${N(a)} ✅. Деление — обратное действие к умножению, поэтому знаки работают так же.`};});
